package dev.zomboid.gore;
import java.util.*;
/** Keep armor UVs and lighting; subtract holes on the impacted region only. */
public final class Armor48 {
 record Cached(int hash,List<Mesh12.Cube> cubes,List<Mesh12.Quad> mesh){}
 static final Map<Object,Cached> CACHE=Collections.synchronizedMap(new WeakHashMap<>());
 static final Map<Object,Integer> PARTS=Collections.synchronizedMap(new WeakHashMap<>());
 public static void bind(Object model){if(model==null)return;String[] names={"head","body","leftArm","rightArm","leftLeg","rightLeg","hat"};int[] regions={0,6,2,3,4,5,0};for(int i=0;i<names.length;i++)try{Object p=R.get(model,names[i]);PARTS.put(p,regions[i]);}catch(IllegalStateException ignored){}}
 public static boolean render(Object part,Object pose,Object vc,int light,int overlay,int color){Integer region=PARTS.get(part);if(region==null||Skin12.CURRENT.get()==null||!Cuts24.has(region))return false;if(!R.yes(R.get(part,"visible"))||R.yes(R.get(part,"skipDraw")))return false;List<Mesh12.Cube> cubes=Model25.cubes(part,region);if(cubes.isEmpty())return false;int hash=Arrays.hashCode(Cuts24.CURRENT.get());Cached cached=CACHE.get(part);if(cached==null||cached.hash()!=hash||cached.cubes()!=cubes){cached=new Cached(hash,cubes,mesh(cubes,region));CACHE.put(part,cached);}List<Mesh12.Quad> mesh=cached.mesh();R.call(pose,"pushPose");try{R.call(part,"translateAndRotate",pose);Object p=R.call(pose,"last");for(Mesh12.Quad q:mesh)for(int j=0;j<4;j++){Mesh12.Vertex xyz=q.vertices()[j];Object v=R.call(vc,"addVertex",p,xyz.x()/16,xyz.y()/16,xyz.z()/16);R.call(v,"setColor",q.material()==48?shade(color):color);R.call(v,"setUv",xyz.u(),xyz.v());R.call(v,"setOverlay",overlay);R.call(v,"setLight",light);R.call(v,"setNormal",p,q.nx(),q.ny(),q.nz());}}finally{R.call(pose,"popPose");}return true;}

 static int shade(int color){return color&0xff000000|((color>>16&255)/4)<<16|((color>>8&255)/4)<<8|(color&255)/4;}
 static List<Mesh12.Quad> mesh(List<Mesh12.Cube> cubes,int region){Mesh12.Box bounds=CSG24.bounds(cubes);List<Mesh12.Box> holes=CSG24.holes(bounds,region,0);List<Mesh12.Quad> mesh=new ArrayList<>();for(Mesh12.Cube cube:cubes)for(Mesh12.Face f:cube.faces())CSG24.surface(mesh,f,holes);
  // Small non-destructive hits leave dark cracks rather than stripping the armor layer.
  int[] cuts=Cuts24.CURRENT.get();for(int k=0;k<cuts.length;k+=2){Cuts24.Cut cut=Cuts24.cut(cuts,k);if(cut.region()!=region&&!(region==6&&cut.region()==7)||cut.style()!=2)continue;int axis=Wound28.normal(cut);int[]t=Wound28.tangent(axis);float[]min={bounds.x0(),bounds.y0(),bounds.z0()},max={bounds.x1(),bounds.y1(),bounds.z1()};double[]q={cut.x(),cut.y(),cut.z()};float[]v=new float[3];for(int a=0;a<3;a++)v[a]=(float)(min[a]+q[a]*(max[a]-min[a]));v[axis]=q[axis]<.5?min[axis]-.025f:max[axis]+.025f;float[]lo=v.clone(),hi=v.clone();float size=(float)Math.min(1.1,.35+cut.radius()*.2);lo[t[0]]=Math.max(min[t[0]],v[t[0]]-size);hi[t[0]]=Math.min(max[t[0]],v[t[0]]+size);lo[t[1]]=Math.max(min[t[1]],v[t[1]]-.07f);hi[t[1]]=Math.min(max[t[1]],v[t[1]]+.07f);lo[axis]-=.006f;hi[axis]+=.006f;List<Mesh12.Quad> scar=new ArrayList<>();Mesh12.box(scar,new Mesh12.Box(lo[0],lo[1],lo[2],hi[0],hi[1],hi[2]),8,null);for(Mesh12.Quad face:scar)mesh.add(new Mesh12.Quad(face.vertices(),48,face.nx(),face.ny(),face.nz()));}return List.copyOf(mesh);}
}